from contextlib import contextmanager
import os
import triton


class TileIREnvConf:
    @staticmethod
    def enable_approx():
        # Enable approximate calculation, trading off numerical precision for performance gains
        return os.getenv("TILEIR_ENABLE_APPROX", "0") == "1"

    @staticmethod
    def enable_ftz():
        # Enable flush denormal to zero, trading off numerical precision for performance gains
        return os.getenv("TILEIR_ENABLE_FTZ", "0") == "1"

    @staticmethod
    def enable_autogen_alias_mem_token():
        return os.getenv("TILEIR_ENABLE_AUTOGEN_ALIAS_MEM_TOKEN", "1") == "1"

    @staticmethod
    def get_fmad_flag():
        # Default to True, but allow disabling via env var
        return os.getenv("TILE_IR_DISABLE_FMAD", "0") != "1"

    @staticmethod
    def get_tileiras_path():
        # Resolution order: explicit env override > bundled binary > system PATH.
        env_path = os.getenv("TRITON_TILEIRAS_PATH", None)
        if env_path is not None:
            return os.path.join(env_path, "tileiras")

        # Bundled binary downloaded at build time into the self-contained
        # tileir CUDA root (backends/nvidia/tileir_cuda/bin/tileiras), alongside
        # the bundled 13.3 ptxas + libnvvm/libdevice.
        bundled_path = os.path.join(
            os.path.dirname(triton.__file__),
            "backends",
            "nvidia",
            "tileir_cuda",
            "bin",
            "tileiras",
        )
        if os.path.isfile(bundled_path) and os.access(bundled_path, os.X_OK):
            return bundled_path

        # Fall back to system PATH.
        from shutil import which

        tileiras_path = which("tileiras")
        if tileiras_path is None:
            raise RuntimeError(
                "tileiras not found: TRITON_TILEIRAS_PATH unset, no bundled "
                "binary, and not in PATH"
            )
        return tileiras_path

    @staticmethod
    def get_tileir_cuda_home():
        # CUDA_HOME used by the tileiras subprocess to find ptxas + libnvvm +
        # libdevice for SM100 codegen. DERIVED purely from the resolved tileiras
        # location (tileiras always lives in <CUDA_HOME>/bin/tileiras): take
        # dirname(dirname(tileiras)). We deliberately do NOT read the system
        # CUDA_HOME env var, so a stale/older system CUDA (e.g. 13.2) can never
        # shadow the bundled 13.3 toolchain. Resolution therefore follows
        # get_tileiras_path():
        #   TRITON_TILEIRAS_PATH set -> dirname(TRITON_TILEIRAS_PATH)
        #   bundled                 -> backends/nvidia/tileir_cuda
        #   PATH                    -> dirname(dirname(which("tileiras")))
        # Injected ONLY into the tileiras subprocess env (see compiler.py).
        tileiras = TileIREnvConf.get_tileiras_path()
        return os.path.dirname(os.path.dirname(tileiras))

    @staticmethod
    def get_device():
        return "cpu" if os.environ.get("ENABLE_CPU_TORCH", False) else "cuda"

    @staticmethod
    def in_nightly_pipeline():
        return os.getenv("RUN_FULL_TEST", "0") == "1"

    @staticmethod
    def in_release_pipeline():
        """Check if running in release pipeline environment"""
        return os.getenv("NVT_RUN_RELEASE_PIPELINE", "0") == "1"

    @staticmethod
    def get_sm_arch():
        import torch

        device = "cuda"
        cc = torch.cuda.get_device_capability(device)
        sm_arch = f"sm{cc[0]}{cc[1]}"
        return sm_arch

    @staticmethod
    def enable_tma_offset_assert_check():
        return os.getenv("NVT_TMA_OFFSET_CHECK", "0") == "1"


@contextmanager
def set_env_var(var_name, new_value):
    # Save the original value of the environment variable
    original_value = os.getenv(var_name, None)

    # Set the new value
    if new_value is None and var_name in os.environ:
        del os.environ[var_name]
    elif new_value is not None:
        os.environ[var_name] = str(new_value)
    try:
        yield
    finally:
        # Reset to the original value or remove the variable
        if original_value is not None:
            os.environ[var_name] = original_value
        elif var_name in os.environ:
            del os.environ[var_name]

from triton.errors import TritonError


class HitFallback(TritonError):
    def __init__(self, required, name):
        self.required = required
        self.name = name

    def __str__(self) -> str:
        return f"HitFallback: {self.name}, Required: {self.required}."

    def __reduce__(self):
        # this is necessary to make CompilationError picklable
        return (type(self), (self.required, self.name))

from ..errors import TritonError
from typing import Optional


class InterpreterError(TritonError):

    def __init__(self, error_message: Optional[str] = None):
        self.error_message = error_message

    def __str__(self) -> str:
        return self.error_message or ""


class OutOfResources(TritonError):

    def __init__(self, required, limit, name):
        self.required = required
        self.limit = limit
        self.name = name

    def __str__(self) -> str:
        return f"out of resource: {self.name}, Required: {self.required}, Hardware limit: {self.limit}. Reducing block sizes or `num_stages` may help."

    def __reduce__(self):
        # this is necessary to make CompilationError picklable
        return (type(self), (self.required, self.limit, self.name))


class PTXASError(TritonError):

    def __init__(self, error_message: Optional[str] = None):
        self.error_message = error_message

    def __str__(self) -> str:
        error_message = self.error_message or ""
        return f"PTXAS error: {error_message}"


class TileirasError(TritonError):

    def __init__(self, error_message: Optional[str] = None):
        self.error_message = error_message

    def __str__(self) -> str:
        error_message = self.error_message or ""
        return f"tileiras error: {error_message}"


class AutotunerError(TritonError):

    def __init__(self, error_message: Optional[str] = None):
        self.error_message = error_message

    def __str__(self) -> str:
        error_message = self.error_message or ""
        return f"Autotuner error: {error_message}"

